#!/usr/bin/env Rscript
# Render the package vignettes to a standalone HTML site for GitHub Pages.
#
# This is intentionally NOT pkgdown: it just knits each vignette to HTML with
# rmarkdown and writes a small landing page. The benchmark vignette ships
# PRE-COMPUTED results (a committed table + plot, regenerated by a maintainer),
# so nothing is benchmarked at render time and the heavyweight comparison stack
# (BSgenome/Rsamtools/bench/ggplot2) is NOT needed here -- only the rendering
# toolchain plus the package's own light deps.

out_dir <- "site"
dir.create(out_dir, showWarnings = FALSE, recursive = TRUE)

# Build the package itself first so system.file() resolves the bundled FASTA
# and the benchmark harness is loadable.
message("Rendering vignettes to ", normalizePath(out_dir))

# (vignette file, output html, human title, one-line description)
# Getting Started leads -- it's where a new user should begin.
vignettes <- list(
  list(src = "vignettes/getting-started.Rmd",
       html = "getting-started.html",
       title = "Getting Started",
       desc = "Install the package, connect to a refget store (local or remote), and access sequences with a BSgenome-compatible interface."),
  list(src = "vignettes/benchmark.Rmd",
       html = "benchmark.html",
       title = "Benchmark: BiocRefgetStore vs BSgenome/Biostrings",
       desc = "Reference benchmark comparing RefgetStore-backed sequence extraction against the classic Bioconductor stack: committed timing tables and a comparison plot, regenerable from the package's harness."),
  list(src = "vignettes/reference.Rmd",
       html = "reference.html",
       title = "Reference",
       desc = "Complete reference for every exported constructor, method, and class.")
)

rendered <- character(0)
for (v in vignettes) {
  message("== rendering ", v$src)
  ok <- tryCatch({
    rmarkdown::render(
      input = v$src,
      output_format = "html_document",
      output_file = v$html,
      output_dir = out_dir,
      output_options = list(
        toc = TRUE, toc_float = TRUE, self_contained = TRUE,
        theme = "cosmo"
      ),
      quiet = FALSE,
      envir = new.env()
    )
    TRUE
  }, error = function(e) {
    message("!! FAILED to render ", v$src, ": ", conditionMessage(e))
    FALSE
  })
  if (ok) rendered <- c(rendered, v$html)
}

# The benchmark vignette is the headline; fail the build if it didn't render,
# so a broken benchmark page never silently deploys.
if (!"benchmark.html" %in% rendered) {
  stop("benchmark.html did not render; aborting so a broken page is not deployed.")
}

# Landing page. Getting Started leads; the benchmark follows.
links <- vapply(vignettes, function(v) {
  status <- if (v$html %in% rendered) {
    sprintf('<a href="%s">%s</a>', v$html, v$title)
  } else {
    sprintf('<span style="color:#999">%s (failed to render)</span>', v$title)
  }
  sprintf("<li><strong>%s</strong><br/><span class=\"desc\">%s</span></li>",
          status, v$desc)
}, character(1))

index <- sprintf('<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8"/>
<meta name="viewport" content="width=device-width, initial-scale=1"/>
<title>BiocRefgetStore</title>
<style>
  body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
         max-width: 760px; margin: 3rem auto; padding: 0 1rem; line-height: 1.55; color: #1a1a1a; }
  h1 { margin-bottom: 0.2rem; }
  .sub { color: #555; margin-top: 0; }
  ul { list-style: none; padding: 0; }
  li { margin: 1.1rem 0; padding: 1rem 1.2rem; border: 1px solid #e2e2e2; border-radius: 8px; }
  li:first-of-type { border-color: #2b6cb0; background: #f5f9ff; }
  a { color: #2b6cb0; text-decoration: none; font-size: 1.1rem; }
  a:hover { text-decoration: underline; }
  .desc { color: #555; font-size: 0.95rem; }
  footer { margin-top: 2.5rem; color: #888; font-size: 0.85rem; }
</style>
</head>
<body>
<h1>BiocRefgetStore</h1>
<p class="sub">A BSgenome-compatible interface to reference sequences backed by a refget store.</p>
<p><strong>BiocRefgetStore</strong> lets you work with reference genomes in R through
the familiar Bioconductor <code>getSeq()</code> interface &mdash; without managing
FASTA files. Instead of loading a genome from disk, you connect to a
<a href="https://refgenie.org/refget/refgetstore-explained/">RefgetStore</a>
(local or remote) and pull sequences by name or coordinate on demand. Remote
stores stream only the bytes you touch and cache them locally, so you can query
genome-scale collections without downloading them in full.</p>
<p>Under the hood it is powered by <a href="https://github.com/databio/gtars">gtars</a>,
a Rust-backed sequence store, and it plugs into the rest of the Bioconductor
ecosystem (<code>Biostrings</code>, <code>GenomicRanges</code>, <code>Seqinfo</code>).</p>
<p>In benchmarks on the full human genome (GRCh38), RefgetStore-backed extraction
is faster than the classic Bioconductor stack across single-region, bulk, and
whole-chromosome access &mdash; bulk extraction of 2000 regions runs in ~32&nbsp;ms
versus ~390&nbsp;ms for <code>BSgenome::getSeq()</code>. See the benchmark below.</p>
<p><strong>New here?</strong> Start with <a href="getting-started.html">Getting Started</a>.
<strong>What is refget?</strong> See <a href="https://refget.databio.org">refget.databio.org</a>
&mdash; the GA4GH standard for identifying and retrieving reference sequences by
content-based digest &mdash; and the
<a href="https://refgenie.org/refget/refgetstore-explained/">RefgetStore explainer</a>.</p>
<ul>
%s
</ul>
<footer>
Source: <a href="https://github.com/databio/BiocRefgetStore">github.com/databio/BiocRefgetStore</a>.
Pages rendered from the package vignettes by a GitHub Actions workflow.
</footer>
</body>
</html>
', paste(links, collapse = "\n"))

writeLines(index, file.path(out_dir, "index.html"))
message("Wrote ", file.path(out_dir, "index.html"))
message("Rendered: ", paste(rendered, collapse = ", "))
